// Renders the valve markup onto the customer's real frame with sharp
// (libvips + librsvg), so the frame's pixels are never generated by a model.
import sharp from "sharp";

export type SvgForSize = (pixelWidth: number, pixelHeight: number) => string;

export async function drawMarkup(framePath: string, outputPath: string, svgFor: SvgForSize): Promise<string> {
  // rotate() applies EXIF orientation, so the markup lands where the customer sees it.
  const { data, info } = await sharp(framePath).rotate().toBuffer({ resolveWithObject: true });
  await sharp(data)
    .composite([{ input: Buffer.from(svgFor(info.width, info.height)), top: 0, left: 0 }])
    .jpeg({ quality: 88, mozjpeg: true })
    .toFile(outputPath);
  return outputPath;
}
